let financePlanReturn=null;
function financePlanAssumptions(){return '현재 선수 주급과 코치 계약을 유지했을 때의 기본 계획입니다. 코치 급여는 계약 만료까지만 반영합니다. 승리·무승부 보너스, 국내컵·유럽 수입, 이사회·시즌 보상, 앞으로의 영입·계약 변경은 제외합니다.';}
function financePlanRows(m){return '<div class="finance-plan-table"><table><caption>남은 리그 '+m.remaining+'경기 · 결과 확정 때 정산</caption><thead><tr><th>라운드</th><th>경기 수입</th><th>급여</th><th>계획 잔액</th></tr></thead><tbody>'+m.rows.map(r=>'<tr><th scope="row">'+r.round+'R<small>'+escapeText(r.opponent)+' · '+(r.home?'홈':'원정')+'</small></th><td>'+moneyLabel(r.gate+r.sponsor)+'</td><td>'+moneyLabel(r.playerPayroll+r.staffPayroll)+'<small>코치 '+moneyLabel(r.staffPayroll)+'</small></td><td class="'+(r.balance<0?'loss':'')+'">'+signedMoney(r.balance)+'</td></tr>').join('')+'</tbody></table></div>';}
function financePlanSummary(m){return '<div class="finance-plan-kpis"><div><span>지금 자금</span><strong>'+signedMoney(m.current)+'</strong></div><div><span>남은 리그 기본 순수익</span><strong>'+signedMoney(m.net)+'</strong></div><div><span>기본 계획 후 잔액</span><strong class="'+(m.ending<0?'loss':'')+'">'+signedMoney(m.ending)+'</strong></div></div>';}
function financePlanLow(m){return m.low<0?'<p class="finance-plan-warning">'+(m.lowRound?m.lowRound+'R 정산 뒤':'현재')+' 기본 계획의 최저 잔액 '+signedMoney(m.low)+'. 자금이 부족해도 경기는 계속할 수 있습니다.</p>':'';}
function renderFinancePlan(){
 const host=$('finance-plan-panel');if(!host||typeof view!=='undefined'&&view!=='market')return;const m=FinancePlan.read(season),expanded=host.querySelector('.finance-plan-rounds')?.open||false,opened=host.querySelector('.finance-plan-collapse')?.open||false;
 host.innerHTML='<section class="finance-plan" aria-labelledby="finance-plan-title"><details class="finance-plan-collapse"'+(opened?' open':'')+'><summary><h2 id="finance-plan-title">남은 리그 자금 계획</h2><span>'+m.year+'시즌 · '+m.remaining+'경기 · 계산 내역</span></summary>'+financePlanSummary(m)+financePlanLow(m)+'<p class="finance-plan-note">'+(m.remaining?'실제 최종 자금을 예측하는 값은 아닙니다. 영입 후보의 자금 계획 비교에서 계약 후 차이도 살펴보세요.':'이번 시즌 리그 정산이 모두 끝났습니다. 남은 대회 수입은 이 계획에 포함하지 않습니다.')+'</p><details class="finance-plan-rounds"'+(expanded?' open':'')+'><summary>계산 기준과 라운드별 내역</summary><p class="finance-plan-note">'+financePlanAssumptions()+'</p>'+financePlanRows(m)+'</details></details></section>';
}
function openFinancePlan(identity,slot){
 const dialog=$('finance-plan-dialog');if(!dialog)return;const baseline=FinancePlan.read(season),m=FinancePlan.read(season,{identity,slot}),d=m.deal,esc=escapeText;financePlanReturn=document.activeElement;
 dialog.innerHTML='<div class="finance-plan-head"><div><span class="eyebrow">영입 예산</span><h2 id="finance-plan-dialog-title">영입 후 자금 비교</h2></div><button type="button" id="close-finance-plan" class="secondary" aria-label="자금 비교 닫기">×</button></div><div class="finance-plan-body"><p class="finance-plan-transfer">'+esc(d.outgoing)+' → <strong>'+esc(d.incoming)+'</strong></p><p class="finance-plan-note">비교 화면입니다. 영입은 후보 카드의 영입 버튼으로 진행합니다.</p><dl class="finance-plan-deal"><div><dt>영입 지출 · 수수료 포함</dt><dd>'+signedMoney(d.cost)+'</dd></div><div><dt>즉시 남는 자금</dt><dd class="'+(m.starting<0?'loss':'')+'">'+signedMoney(m.starting)+'</dd></div><div><dt>선수 주급 변화</dt><dd>'+signedMoney(d.wageChange)+'</dd></div><div><dt>남은 '+m.remaining+'경기 선수 급여 차이</dt><dd>'+signedMoney(d.wageChange*m.remaining)+'</dd></div></dl><div class="finance-plan-comparison"><article><span>현재 선수단 유지</span><strong>'+signedMoney(baseline.ending)+'</strong></article><article><span>이 영입 후 유지</span><strong class="'+(m.ending<0?'loss':'')+'">'+signedMoney(m.ending)+'</strong><small>기본 계획 차이 '+signedMoney(m.ending-baseline.ending)+'</small></article></div>'+(m.starting<0?'<p class="finance-plan-warning">현재 자금으로는 이 영입을 진행할 수 없습니다.</p>':'')+financePlanLow(m)+'<p class="finance-plan-note">'+financePlanAssumptions()+'</p><details><summary>영입 후 라운드별 내역</summary>'+financePlanRows(m)+'</details></div>';
 const close=()=>{dialog.close();financePlanReturn?.focus?.({preventScroll:true});};$('close-finance-plan').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};if(!dialog.open)dialog.showModal();$('close-finance-plan').focus({preventScroll:true});
}
